+        using var scope = scopeFactory.CreateScope();
+        var db = scope.ServiceProvider.GetRequiredService<Data.ApplicationDbContext>();
+        return await db.Shipments.Select(s => ToModel(s)).ToListAsync();
+    }
+
+    public async Task<Client.Models.Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
+    {
+        using var scope = scopeFactory.CreateScope();
+        var db = scope.ServiceProvider.GetRequiredService<Data.ApplicationDbContext>();
+        var entity = await db.Shipments
+            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
+        return entity is null ? null : ToModel(entity);
+    }
+
+    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
+    {
+        using var scope = scopeFactory.CreateScope();
+        var db = scope.ServiceProvider.GetRequiredService<Data.ApplicationDbContext>();
+        var entity = await db.Shipments.FindAsync(id);
+        if (entity is not null)
+        {
+            entity.Status = status;
+            await db.SaveChangesAsync();
+        }
+    }
+
+    private static Client.Models.Shipment ToModel(Data.Shipment s) => new()
+    {
+        Id = s.Id,
+        TrackingNumber = s.TrackingNumber,
+        Origin = s.Origin,
+        Destination = s.Destination,
+        Status = s.Status,
+        ShippedDate = s.ShippedDate,
+        EstimatedDelivery = s.EstimatedDelivery,
+        CustomerEmail = s.CustomerEmail,
+        Description = s.Description
+    };
+}
